\title{Explicit Reciprocity from Roots of Unity to Class Numbers:\\ Steps Toward Hilbert's Twelfth Problem}
\author{Aristotle}
\date{2026-07-02}

\begin{document}
\begin{abstract}
Hilbert's twelfth problem asks for an explicit construction of the abelian extensions of an
arbitrary number field, generalizing the Kronecker--Weber theorem, which realizes every abelian
extension of the rationals inside a cyclotomic field. We develop the arithmetic consequences of
the abelian ($\mathrm{GL}_1$) reciprocity law in two settings. Over the rationals, we harvest the
group-theoretic invariants of cyclotomic Galois groups from the Artin reciprocity isomorphism
$(\Z/n\Z)^\times \cong \Gal(\Q(\zeta_n)/\Q)$: the order of the group equals Euler's totient
$\varphi(n)$, and for prime modulus $p$ the group is cyclic of order $p-1$. We show by explicit
example ($n=8$) that cyclicity genuinely requires the prime hypothesis. We then take the first
structural step beyond $\Q$ by studying the Hilbert class field $H$ of a number field $K$,
characterized by the higher reciprocity isomorphism $\Gal(H/K)\cong \Cl(\Ok)$. From this
isomorphism we derive the fundamental degree law $[H:K] = h_K$, where $h_K$ is the class number,
and the corollary that class number one forces $H = K$. We verify non-vacuity by instantiating the
reciprocity datum for $K = H = \Q$. Throughout, the emphasis is on turning abstract reciprocity
isomorphisms into exact, computable numerical invariants.
\end{abstract}

\maketitle

\section{Introduction}
Class field theory describes the abelian extensions of a number field $K$ --- its finite Galois
extensions with commutative Galois group --- in terms of the arithmetic of $K$ itself. Its
foundational special case is the \emph{Kronecker--Weber theorem}: every abelian extension of $\Q$
is contained in a cyclotomic field $\Q(\zeta_n)$, obtained by adjoining a primitive $n$-th root of
unity. Hilbert's twelfth problem asks for the analogous \emph{explicit} generators for an
arbitrary base field $K$.

This paper is organized around a single principle: an abelian reciprocity isomorphism does more
than match two objects set-theoretically; it forces their numerical and structural invariants to
coincide. We exploit this twice. Over $\Q$, the Artin reciprocity isomorphism
$\rho_n : (\Z/n\Z)^\times \xrightarrow{\sim} \Gal(\Q(\zeta_n)/\Q)$ determines the order and cyclic
type of the cyclotomic Galois group (Section~\ref{sec:cyc}). Over an arbitrary number field $K$,
the higher reciprocity isomorphism $\Gal(H/K)\xrightarrow{\sim}\Cl(\Ok)$ characterizing the
Hilbert class field $H$ determines the degree $[H:K]$ (Section~\ref{sec:hcf}).

\section{Definitions and background}
Throughout, $n$ denotes a positive integer and $\zeta_n$ a primitive $n$-th root of unity.

\begin{definition}[Cyclotomic field]
The $n$-th \emph{cyclotomic field} is $\Q(\zeta_n)$, the smallest subfield of $\mathbb{C}$
containing $\Q$ and $\zeta_n$. It is a Galois extension of $\Q$.
\end{definition}

\begin{definition}[Galois group]
For a finite Galois extension $L/K$, the \emph{Galois group} $\Gal(L/K)$ is the group of field
automorphisms of $L$ fixing $K$ pointwise. Its cardinality equals the degree $[L:K] = \dim_K L$.
\end{definition}

\begin{definition}[Euler totient]
For $n\ge 1$, $\varphi(n) = \#\{\,k : 1\le k\le n,\ \gcd(k,n)=1\,\} = \#(\Z/n\Z)^\times$.
\end{definition}

\begin{definition}[Cyclic group]
A finite group $G$ is \emph{cyclic} if there exists $g\in G$ with $G=\langle g\rangle$;
equivalently $G\cong \Z/|G|\Z$.
\end{definition}

\begin{definition}[Class group and class number]
For a number field $K$, let $\Ok$ be its ring of integers. The \emph{ideal class group} $\Cl(\Ok)$
is the quotient of the group of nonzero fractional ideals by the principal fractional ideals; it is
a finite abelian group. The \emph{class number} is $h_K = \#\,\Cl(\Ok)$, with $h_K = 1$ iff $\Ok$
is a principal ideal domain.
\end{definition}

\begin{definition}[Hilbert class field]
The \emph{Hilbert class field} $H$ of $K$ is the maximal unramified abelian extension of $K$; its
defining property is the Artin reciprocity isomorphism $\Gal(H/K)\cong \Cl(\Ok)$.
\end{definition}

\section{The cyclotomic case over $\Q$}\label{sec:cyc}
The foundation for this section is the abelian reciprocity isomorphism over the rationals.

\begin{remark}[Artin reciprocity over $\Q$]\label{rem:rho}
For every modulus $n$ there is a canonical group isomorphism
$\rho_n : (\Z/n\Z)^\times \xrightarrow{\sim} \Gal(\Q(\zeta_n)/\Q)$, sending the class of $k$ to the
automorphism $\sigma_k : \zeta_n \mapsto \zeta_n^{\,k}$. It is constructed unconditionally for
every $n$.
\end{remark}

\begin{theorem}[Degree of the cyclotomic extension]\label{thm:deg}
For every $n\ge 1$, $\#\,\Gal(\Q(\zeta_n)/\Q) = \varphi(n)$, and hence
$[\Q(\zeta_n):\Q] = \varphi(n)$.
\end{theorem}
\begin{proof}[Proof sketch]
The isomorphism $\rho_n$ is a bijection, so $\#\,\Gal(\Q(\zeta_n)/\Q) = \#(\Z/n\Z)^\times =
\varphi(n)$. Since the order of the Galois group of a finite Galois extension equals its degree,
$[\Q(\zeta_n):\Q] = \varphi(n)$. Only $n\neq 0$ is required.
\end{proof}

\begin{theorem}[Cyclicity for prime modulus]\label{thm:cyc}
For a prime $p$, $\Gal(\Q(\zeta_p)/\Q)$ is cyclic.
\end{theorem}
\begin{proof}[Proof sketch]
The multiplicative group of a finite field is cyclic; in particular $(\Z/p\Z)^\times = \mathbb{F}_p^\times$
is cyclic. Cyclicity is preserved under group isomorphism, so transporting along $\rho_p$ gives the
result.
\end{proof}

\begin{theorem}[Order for prime modulus]\label{thm:ord}
For a prime $p$, $\#\,\Gal(\Q(\zeta_p)/\Q) = p - 1$.
\end{theorem}
\begin{proof}[Proof sketch]
By Theorem~\ref{thm:deg} the order is $\varphi(p) = p-1$.
\end{proof}

Combining Theorems~\ref{thm:cyc} and \ref{thm:ord}: $\Gal(\Q(\zeta_p)/\Q)\cong \Z/(p-1)\Z$, and a
generator corresponds under $\rho_p$ to a primitive root modulo $p$.

\begin{proposition}[Cyclicity fails for $n=8$]\label{prop:eight}
$\Gal(\Q(\zeta_8)/\Q)$ is not cyclic; it is isomorphic to $\Z/2\Z\times\Z/2\Z$.
\end{proposition}
\begin{proof}[Proof sketch]
Under $\rho_8$ the group is $(\Z/8\Z)^\times = \{1,3,5,7\}$. Each element squares to $1$ modulo $8$,
so every non-identity element has order $2$; a cyclic group of order $4$ would contain an element
of order $4$. Hence the group is the Klein four-group.
\end{proof}

Thus the prime hypothesis in Theorems~\ref{thm:cyc}--\ref{thm:ord} is load-bearing.

\section{The Hilbert class field of a general number field}\label{sec:hcf}
Let $K$ be a number field with ring of integers $\Ok$ and Hilbert class field $H$. We isolate the
single property that makes $H$ useful and treat it as an explicit hypothesis.

\begin{remark}[Artin reciprocity for the Hilbert class field]\label{rem:e}
There is a group isomorphism $e : \Gal(H/K)\xrightarrow{\sim}\Cl(\Ok)$.
\end{remark}

\begin{theorem}[Degree equals class number]\label{thm:hcf}
Let $K$ be a number field and $H/K$ a finite Galois extension equipped with a reciprocity
isomorphism $e:\Gal(H/K)\cong \Cl(\Ok)$. Then $[H:K] = h_K$.
\end{theorem}
\begin{proof}[Proof sketch]
For a finite Galois extension $\#\,\Gal(H/K) = [H:K]$. The isomorphism $e$ is a bijection, so
$\#\,\Gal(H/K) = \#\,\Cl(\Ok) = h_K$. Chaining the equalities gives $[H:K] = h_K$.
\end{proof}

\begin{corollary}[Class number one]\label{cor:one}
Under the hypotheses of Theorem~\ref{thm:hcf}, if $h_K = 1$ then $[H:K] = 1$; equivalently $H = K$.
\end{corollary}
\begin{proof}[Proof sketch]
Immediate from $[H:K] = h_K = 1$.
\end{proof}

\begin{proposition}[Rational witness]\label{prop:rat}
For $K = H = \Q$, the reciprocity isomorphism $e$ exists: both $\Gal(\Q/\Q)$ and $\Cl(\Z)$ are
trivial, so the unique map between them is an isomorphism. Consequently Theorem~\ref{thm:hcf}
instantiates to $[\Q:\Q] = h_\Q = 1$.
\end{proposition}
\begin{proof}[Proof sketch]
$\Ok = \Z$ is a principal ideal domain, so $\Cl(\Z)$ is trivial and $h_\Q = 1$; $\Gal(\Q/\Q)$ is
trivial. Any map between trivial groups is an isomorphism, providing $e$, and
Theorem~\ref{thm:hcf} yields $[\Q:\Q] = 1$.
\end{proof}

\section{Algorithms}
\textbf{Algorithm A (Cyclotomic degree and cyclic type).} Given $n$, compute $\varphi(n)$ from the
factorization $n=\prod p_i^{a_i}$ via $\varphi(n)=\prod p_i^{a_i-1}(p_i-1)$; this is
$[\Q(\zeta_n):\Q]$. The group is cyclic iff $n\in\{1,2,4,p^k,2p^k\}$ for an odd prime $p$; in the
prime case a generator is a primitive root modulo $p$.

\medskip
\noindent\textbf{Algorithm B (Hilbert class field degree).} Given $K$, compute $\Cl(\Ok)$ (e.g.\ via
Minkowski's bound), and read off $[H:K] = h_K$; then $H = K$ iff $h_K = 1$.

\section{Discussion and future directions}
Reciprocity transports arithmetic invariants ($\varphi(n)$, cyclicity, the class number) onto
structural invariants of field extensions (degree, Galois type). This is the abelian
$\mathrm{GL}_1$ layer of the Langlands program. The Hilbert class field marks the genuine departure
from Kronecker--Weber: over $\Q$ the reciprocity partner is $(\Z/n\Z)^\times$, while over a general
$K$ it is the ideal class group, and $[H:K] = h_K$ is the precise analogue of
$[\Q(\zeta_n):\Q] = \varphi(n)$.

Future directions include: \emph{conductor duality} for cyclotomic subfields (the conductor as a
computable arithmetic invariant forced by group-theoretic index); \emph{class-number rigidity of
the Hilbert tower} (successive degrees are class numbers, making the tower an exactly computable
integer sequence); \emph{prime-cyclicity transfer} to the maximal real subfield of $\Q(\zeta_p)$, a
cyclic extension of degree $(p-1)/2$; and the \emph{complex-multiplication analogue} of
Kronecker--Weber for imaginary quadratic fields, generating abelian extensions via special values
of modular and elliptic functions.

\section{Conclusion}
Starting from the abelian reciprocity isomorphisms, we extracted exact numerical invariants: the
degree of a cyclotomic field is Euler's totient, prime moduli yield cyclic Galois groups of order
$p-1$ (with the prime hypothesis necessary, as $n=8$ shows), and the degree of a Hilbert class
field equals the class number, collapsing to a trivial extension exactly when factorization is
unique.

