function CLASS_NUMBER(d):
    D <- (-d if (-d) mod 4 = 1 else -4d)
    count <- 0; a <- 1
    while a*a <= floor(-D/3) + 1:
        for b in [-a .. a]:
            if (b*b - D) not divisible by 4a: continue
            c <- (b*b - D) / (4a)
            if c < a: continue
            if |b| <= a <= c:
                if (|b| = a or a = c) and b < 0: continue
                count <- count + 1
        a <- a + 1
    return count   # = h_K = [H:K]

